import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { createServer } from 'vite';
const loader = await createServer({ configFile: false, optimizeDeps: { noDiscovery: true, entries: [] }, server: { middlewareMode: true, watch: null, hmr: false, ws: false }, appType: 'custom' });
const checks = [];
try {
  const { buildDesign, DEFAULT_CONFIG } = await loader.ssrLoadModule('/src/twin/assets/design.ts');
  const { initialize, advanceWithStep } = await loader.ssrLoadModule('/src/twin/engine/simulation.ts');
  const { validateState } = await loader.ssrLoadModule('/src/twin/persistence/state.ts');
  const { resultsCSV, inventoryCSV } = await loader.ssrLoadModule('/src/twin/analysis/reports.ts');
  const design = buildDesign({ ...DEFAULT_CONFIG, requestedAccelerators: 8 });
  const initial = initialize(design);
  assert.match(resultsCSV(design, initial), /coolantK/);
  assert.match(inventoryCSV(design), /assetId/);
  const invalidState = structuredClone(initial);
  invalidState.modules[0].coolantK = Infinity;
  assert.throws(() => resultsCSV(design, invalidState), e => e.diagnostic?.kind === 'invalid-input');
  checks.push({ name: 'direct results CSV rejects nonfinite state; valid CSV still exports', status: 'PASS' });
  const invalidDesign = structuredClone(design);
  invalidDesign.config.supplyW = Infinity;
  assert.throws(() => inventoryCSV(invalidDesign), e => e.diagnostic?.kind === 'invalid-input');
  checks.push({ name: 'direct inventory CSV rejects nonfinite design; valid CSV still exports', status: 'PASS' });
  const duty = `${design.modules[0].id}/pump-duty`;
  const state = advanceWithStep(design, initial, 1, [{ id: 'trip', timeS: 0, kind: 'trip', assetId: duty }], 0.125);
  validateState(design, state);
  const standby = `${design.modules[0].id}/pump-standby`;
  assert.equal(state.modules[0].states[standby], 'starting');
  assert.ok(state.modules[0].startAtS[standby] > state.timeS);
  const invalidDeadline = structuredClone(state);
  invalidDeadline.modules[0].startAtS[standby] += 0.0625;
  assert.throws(() => validateState(design, invalidDeadline), e => e.diagnostic?.code === 'STATE_DEADLINE_GRID');
  checks.push({ name: 'actual pending startup validates on fractional grid and rejects half-grid corruption', status: 'PASS', integrationStepS: state.integrationStepS, checkpointTimeS: state.timeS, validDeadlineS: state.modules[0].startAtS[standby], rejectedDeadlineS: invalidDeadline.modules[0].startAtS[standby] });
} finally { await loader.close(); }
const result = { status: 'PASS', checkedAt: new Date().toISOString(), checks };
await fs.writeFile('artifacts/phase-1-review/committed-boundary-probes.json', JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify(result, null, 2));
